SELECT stat_date AS statDate, sku_id AS skuId,
warehouse_id
0
AS warehouseId, SUM(qty_on_hand) AS qtyOnHand, SUM(qty_locked) AS qtyLocked, SUM(qty_transit) AS qtyTransit, SUM(qty_available) AS qtyAvailable FROM inventory_snapshot_daily WHERE sku_id = #{skuId} AND stat_date >= #{from} AND stat_date <= #{to}
AND warehouse_id = #{warehouseId}
GROUP BY stat_date, sku_id
, warehouse_id
ORDER BY stat_date LIMIT #{limit}
